-- Monarch entry-point Hyprland configuration.
--
-- monarch-refresh-hypr installs this file at ~/.config/hypr/hyprland.lua and
-- replaces @MONARCH_PATH@ with the runtime root. Do not edit the installed copy.
-- Customise Monarch in the user-owned files in ~/.config/hypr/ (loaded last, so
-- they win): monitors.lua, input.lua, bindings.lua, looknfeel.lua, autostart.lua.
-- See https://wiki.hypr.land/configuring/

local root = "@MONARCH_PATH@"
local user = os.getenv("HOME") .. "/.config/hypr"

monarch = dofile(root .. "/default/hypr/lib.lua")
monarch.root = root

monarch.default("env")
monarch.default("input")
monarch.default("autostart")
monarch.default("looknfeel")
monarch.default("workspaces")
monarch.default("rules")
for _, name in ipairs({ "system", "tiling", "grouping", "utilities", "media" }) do
  monarch.default("binds/" .. name)
end

-- Shell layer (bar, launcher, notifications, lock, wallpaper, OSD): owns the
-- monarch-shell-start autostart, its key bindings and layer rules.
monarch.default("shell")

-- Runtime toggles (flag files managed by monarch-toggle)
local toggles = os.getenv("HOME") .. "/.local/state/monarch/toggles"
for _, name in ipairs({ "single-window-aspect-ratio", "window-no-gaps" }) do
  if io.open(toggles .. "/" .. name, "r") then
    monarch.default("toggles/" .. name)
  end
end

-- Console keyboard layout, generated by install/user/detect-keyboard-layout.sh
monarch.optional(user .. "/keyboard.lua")

-- User overrides
monarch.optional(user .. "/monitors.lua")
monarch.optional(user .. "/input.lua")
monarch.optional(user .. "/bindings.lua")
monarch.optional(user .. "/looknfeel.lua")
monarch.optional(user .. "/autostart.lua")
